    with wave.open(str(output), "wb") as wav:
        wav.setnchannels(1)
        wav.setsampwidth(2)
        wav.setframerate(48000)
        wav.writeframes(recorded)
    return {
        "result": "passed",
        "mode": "offline diagnostic tones (no AI speech)",
        "greeting_transport_ms": round(greeting_ms, 2),
        "interruption": "passed",
        "cleanup": "passed",
        "wav": str(output),
    }
