  node.buffer = buffer;
  node.connect(context.destination);
  const at = Math.max(context.currentTime + 0.025, playbackUntil);
  node.start(at);
  playbackUntil = at + buffer.duration;
  sources.add(node);
  node.onended = () => {
    sources.delete(node);
    node.disconnect();
  };
  lastActivity = performance.now();
  setPhase("speaking");
}
function startSession() {
  if (!enabled || socket) return;
  trigger.reset();
  setPhase("connecting");
  pending = preRoll.slice();
  preRoll = [];
  const ws = new WebSocket(
    `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/audio/stream`,
  );
  socket = ws;
  ws.binaryType = "arraybuffer";
  startedAt = performance.now();
  lastActivity = startedAt;
  startupTimer = setTimeout(() => {
    if (socket === ws)
      void fail(
        "The assistant did not start in time. Check the server and API credentials.",
      );
  }, 18000);
  ws.onopen = () => {
    if (socket === ws)
      ws.send(
        JSON.stringify({
          event: "start",
          encoding: "pcm_s16le",
          sample_rate: 24000,
          channels: 1,
        }),
      );
  };
